import Foundation
import Testing
@testable import RemoteDesktopCore

/// The packaged .app keeps SwiftPM resource bundles in `Contents/Resources`, which the accessor
/// generated by older SwiftPM never looks at (it crashed the 1.1.0 release at launch).
@Suite struct CoreBundleTests {
    private static func makeApp() throws -> URL {
        let app = FileManager.default.temporaryDirectory.appending(path: "CoreBundleTests-\(UUID().uuidString)/Test.app")
        try FileManager.default.createDirectory(
            at: app.appending(path: "Contents/Resources/\(Bundle.coreBundleName).bundle"),
            withIntermediateDirectories: true)
        return app
    }

    @Test func findsTheBundleInTheAppsResources() throws {
        let app = try Self.makeApp()
        defer { try? FileManager.default.removeItem(at: app.deletingLastPathComponent()) }
        let resources = app.appending(path: "Contents/Resources")

        let bundle = try #require(Bundle.resourceBundle(named: Bundle.coreBundleName, in: [resources, app]))
        #expect(bundle.bundleURL.standardizedFileURL
            == resources.appending(path: "\(Bundle.coreBundleName).bundle").standardizedFileURL)
    }

    @Test func returnsNilWhenNoCandidateHasTheBundle() throws {
        let app = try Self.makeApp()
        defer { try? FileManager.default.removeItem(at: app.deletingLastPathComponent()) }

        #expect(Bundle.resourceBundle(named: Bundle.coreBundleName, in: [app, nil]) == nil)
    }

    /// Not its localizations: under `swift test` older SwiftPM ships the String Catalog uncompiled.
    @Test func coreIsTheCoreResourceBundle() {
        #expect(Bundle.core.bundleURL.lastPathComponent == "\(Bundle.coreBundleName).bundle")
    }
}
